# -*- coding: utf-8 -*-
"""Build static seeds for civil registration, nationality, national ID and passports."""
from __future__ import annotations
import pprint,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; CACHE=ROOT/'data'/'source_cache'; OUT=ROOT/'data'/'seed'/'identity_citizenship.py'
F2A=str.maketrans('۰۱۲۳۴۵۶۷۸۹','0123456789'); A2F=str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹')

def clean(s:str)->str:
    s=re.sub(r'!\[[^]]*\]\([^)]+\)','',s)
    s=re.sub(r'\[([^]]+)\]\([^)]+\)',r'\1',s)
    s=s.replace('**','').replace('__','').replace('\\-','-').replace('\ufeff','').replace('\u00ad','‌').replace('\u200e','‌').replace('\u200f','‌')
    for a,b in {'ي':'ی','ك':'ک','ة':'ه','هیات':'هیأت','آئین':'آیین','مسوول':'مسئول','موسسات':'مؤسسات','لازم الاجرا':'لازم‌الاجرا','ذی ربط':'ذی‌ربط','می باشد':'می‌باشد','می شود':'می‌شود','می گردد':'می‌گردد','می نماید':'می‌نماید','بموجب':'به موجب','بعهده':'به عهده','بعمل':'به عمل','بوسیله':'به وسیله','بایران':'به ایران','بخارج':'به خارج','بتابعیت':'به تابعیت','بسن':'به سن','بوزارت':'به وزارت','بهیچوجه':'به هیچ وجه','بفروش':'به فروش','بعلاوه':'به علاوه','غیر منقوله':'غیرمنقول','قائم مقام':'قائم‌مقام'}.items(): s=s.replace(a,b)
    s=re.sub(r'\[ویرایش\][^\n]*','',s)
    s=re.sub(r'\[\]\([^)]*\)','',s)
    s=re.sub(r'\(https?://[^)]*\)','',s)
    s=re.sub(r'[ \t]*‌[ \t]*','‌',s)
    s=re.sub(r'[ \t]+',' ',s); s=re.sub(r' *\n *','\n',s); s=re.sub(r'\n{3,}','\n\n',s)
    return s.translate(A2F).strip(' \n-*')

def parse_seq(text:str,start:int,end:int,anchor:str|None=None,stop:str|None=None)->dict[str,str]:
    if anchor: text=text.split(anchor,1)[1]
    if stop and stop in text: text=text.split(stop,1)[0]
    # Sequential matching prevents references such as «ماده (۲)» from being mistaken for headings.
    hits=[]; pos=0
    for n in range(start,end+1):
        pnum=str(n); fnum=pnum.translate(A2F)
        pat=re.compile(r'(?<![\w(])(?:\*\*)?[‌\s]*ماده[‌\s]*(?:'+re.escape(fnum)+'|'+pnum+r')[‌\s]*(?:\*\*)?[‌\s]*(?:[-–ـ:)]\s*)?',re.M)
        m=pat.search(text,pos)
        if not m: raise ValueError(f'missing article {n}')
        hits.append((str(n),m.start(),m.end())); pos=m.end()
    out={}
    for i,(k,st,en) in enumerate(hits):
        tail=hits[i+1][1] if i+1<len(hits) else len(text)
        body=text[en:tail]
        body=re.split(r'\n(?:قانون فوق|رئیس مجلس|معاون اول رئیس|### تازه|برچسب ها|دستیار هوشمند)',body,maxsplit=1)[0]
        out[k]=clean(body)
        if not out[k]: raise ValueError(f'empty article {k}')
    return out

def extract_between(text,start,end):
    return clean(text.split(start,1)[1].split(end,1)[0])

