    # The anchor consumes article 1's heading; restore it before parsing.
    regby=parse_seq('ماده ۱ '+(CACHE/'civil_registry_bylaw_1385.md').read_text().split('**ماده ۱**',1)[1],1,14)

    nid=parse_seq((CACHE/'national_id_law.md').read_text(),1,6,anchor='قانون الزام اختصاص شماره ملی و کد پستی برای کلیه اتباع ایرانی (مصوبه')
    nid['6']=nid['6'].split('رسید.',1)[0].strip()+'رسید.'
    nbtxt=(CACHE/'national_id_bylaw_1378.md').read_text().split('آیین نامه اجرایی قانون الزام اختصاص شماره ملی و کدپستی',1)[1]
