    amend_cit=clean(newtxt.split('**ماده‌واحده ـ**',1)[1].split('* * *',1)[0])
    citby=parse_seq((CACHE/'citizenship_children_bylaw_1399.md').read_text(),1,24,anchor='### آیین‌نامه اعطای تابعیت ایران')

    passtxt=(CACHE/'passport_law_current.md').read_text(); passoldtxt=(CACHE/'passport_law_original.md').read_text()
